css:
.p23-page { display: flex; flex-direction: column; gap: var(--s-2); min-height: calc(100cqh - 2 * var(--s-3)); }
.p23-top { display: grid; gap: var(--s-2); }
.p23-top:empty { display: none; }
.p23-stage { position: relative; container-type: size; container-name: p23-stage; flex: 1 1 18rem; min-height: 0; display: flex; align-items: center; justify-content: center; gap: var(--s-2); }
.p23-vp { flex: 0 1 auto; min-width: 0; max-width: calc(100cqw - 4rem); max-height: 100cqh; }
.p23-vp .scheme { width: max(34.75rem, min(calc(100cqw - 4.25rem), calc(100cqh * 1.4912 - 2 * var(--w2)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p23-stage { flex-basis: var(--stage-n, 24.5rem); } }
.p23-tb { position: relative; flex: none; align-self: flex-start; margin-top: var(--s-1); }
.p23-tb .toolbar { gap: var(--s-1); }
.p23-sep { height: var(--w1); background: var(--rule); margin: 0 var(--s-1); }
.p23-tiprow { display: flex; }
.p23-tiprow--end { justify-content: flex-end; }
.p23-tiprow--center { justify-content: center; }
.p23-tiprow .tip { max-width: 100%; }
.p23-pop { position: absolute; z-index: 6; left: calc(var(--x) * 1%); top: calc(var(--y) * 1%); width: max-content; max-width: 15rem; }
.p23-pop--tl { translate: 0 0; }
.p23-pop--c { translate: -50% -50%; }
.p23-pop--tr { translate: -100% 0; }
.p23-pop--bl { translate: 0 -100%; }
.p23-pop--br { translate: -100% -100%; }
.p23-pop--bc { translate: -50% -100%; }
.p23-pop--tc { translate: -50% 0; }
.p23-pop .tip { display: block; max-width: none; }
.p23-tip-lines { display: grid; gap: var(--s-1); }
.p23-tip-lines b { font-weight: var(--fw-bold); }
.scard.frame--full { padding: var(--s-1); }
.scard .scard__name { overflow-wrap: break-word; hyphens: manual; }
.p23-dots { position: absolute; right: 0; bottom: 0; display: none; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p23-dots { display: block; } }
.scard.p23-drag { --frame-color: var(--ink); --frame-w: var(--w2); }
.scard.p23-kfocus { outline: var(--focus-ring); outline-offset: var(--focus-offset); }   
.scard.p23-mini { position: relative; left: auto; top: auto; width: 3.75rem; height: 3.75rem; aspect-ratio: auto; flex: none; }
.p23-un { display: grid; gap: var(--s-2); max-height: 11.25rem; overflow: auto; }
.p23-un__row { display: flex; flex-wrap: wrap; gap: var(--s-2); }
.p23-un.is-over { border: var(--w2) dashed var(--ink); }
.p23-uphint { max-width: none; }
.p23-uptip { display: flex; justify-content: center; }
.p23-uptip .tip { max-width: none; }
.p23-btnwrap { position: relative; display: inline-flex; }
.p23-note { margin-inline-end: auto; }
.p23-err { --frame-w: var(--w2); }
.p23-btnrow { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--s-2); }
.p23-btnrow > .p23-note { flex: 1 1 100%; text-align: center; margin: 0; }
.p23-btnrow > .p23-spacer { display: none; }
.p23-btnrow > .p23-note:empty { display: none; }
.p23-btnwrap .btn[aria-disabled="true"] { cursor: not-allowed; }
@media (min-width: 48rem) and (min-height: 31.25rem) {
  .p23-btnrow > .p23-note, .p23-btnrow > .p23-spacer { display: block; flex: 1 1 0; min-width: 0; text-align: start; }
  .p23-btnrow > .p23-note:empty { display: block; }
}
.p23-load { justify-content: center; padding: var(--s-6) var(--s-3); }
.p23-center { min-height: calc(100cqh - 2 * var(--s-3)); display: grid; justify-items: center; align-content: center; gap: var(--s-3); text-align: center; flex: 1; padding: var(--s-5) var(--s-3); }
.p23-center p { max-width: var(--measure); }
.p23-schint { display: flex; align-items: center; justify-content: center; gap: var(--s-1); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p23-schint { display: none; } }

.p23-cmt.frame { --cw: 12rem; position: absolute; z-index: 4; left: calc(var(--x) * 1%); top: calc(var(--y) * 1%); translate: -50% -50%; display: flex; align-items: center; gap: var(--s-1); width: var(--cw); min-height: 2.875rem; padding: 0 0 0 var(--s-3); border-radius: 50% 50% 50% var(--r); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p23-cmt.frame { --cw: 10.5rem; } }
.p23-cmt__t { flex: 1; min-width: 0; font-size: var(--fs-small); line-height: var(--lh-small); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.p23-cmt__ag { flex: none; }
.p23-cmt--open.frame { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto 1fr auto; align-items: center; gap: 0 var(--s-1); width: 17.5rem; min-height: 9.375rem; padding: var(--s-1) var(--s-3); border-radius: var(--r-soft) var(--r-soft) var(--r-soft) var(--r); translate: -50% 0; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p23-cmt--open.frame { width: 16.875rem; min-height: 8.75rem; } }
.p23-cmt--open .p23-cmt__ag { grid-column: 1; grid-row: 1; justify-self: start; }
.p23-cmt__acts { grid-column: 2; grid-row: 1; display: flex; align-items: center; }
.p23-cmt__body { grid-column: 1 / -1; grid-row: 2; align-self: start; max-height: 6.5rem; overflow: auto; font-size: var(--fs-small); line-height: var(--lh-small); overflow-wrap: anywhere; }
.p23-cmt__fold { grid-column: 1 / -1; grid-row: 3; justify-self: center; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p23-vp.is-focus { overflow: hidden; height: var(--vph, auto); }
  .p23-vp.is-focus .scheme { --sw: 34.75rem; --sh: calc(34.75rem / 1.4912); --vw: calc(100cqw - 4rem); --vh: var(--vph, min(100cqh, var(--sh)));
    translate: clamp(calc(var(--vw) - var(--sw)), calc(var(--vw) / 2 - var(--cx, 50) * var(--sw) / 100), 0px) clamp(calc(var(--vh) - var(--sh)), calc(var(--vh) / 2 - var(--cy, 50) * var(--sh) / 100), 0px); }
}

.p23-errbox { display: grid; gap: var(--s-3); justify-items: start; width: min(100%, 32rem); }
.p23-errbox .banner { width: 100%; }
.p23-emptytxt { position: absolute; inset: 0 4rem 0 0; pointer-events: none; display: grid; place-content: center; justify-items: center; gap: var(--s-1); text-align: center; padding: var(--s-3); }
.p23-emptytxt p { max-width: 24rem; }
.p23-delpop { display: grid; gap: var(--s-2); justify-items: start; padding: var(--s-2) var(--s-3); background: var(--white); max-width: 14rem; }
.p23-delpop p { font-size: var(--fs-cap); line-height: var(--lh-cap); font-weight: var(--fw-medium); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } .tabwrap > .tab { padding-inline: var(--s-1) 1.75rem; font-size: var(--fs-cap); } }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.dialog__head { align-items: center; }
.field__hint { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }

.p23-un.unplaced--layers { max-height: 15rem; gap: var(--s-2); }
.p23-un.unplaced--layers .p23-un__row { gap: calc(var(--scard-off) + var(--s-2)); padding-right: var(--scard-off); }
.scard.p23-mini { overflow: visible; }
.p23-un__row { isolation: isolate; }

.scard.p23-mini .p23-dots { display: none; }
@media (max-width: 22.5rem) {
  .p23-stage { flex-direction: column; align-items: center; justify-content: flex-start; gap: var(--s-1); }
  .p23-stage { flex-basis: calc(var(--stage-n, 24.5rem) + 3.75rem); }
  .p23-tb { order: -1; align-self: center; margin-top: 0; }
  .p23-tb .toolbar { flex-direction: row; }
  .p23-sep { width: var(--w1); height: auto; align-self: stretch; margin: var(--s-1) 0; }
  .p23-vp { max-width: 100cqw; max-height: calc(100cqh - 3.75rem); }
  .p23-vp.is-focus .scheme { --vw: 100cqw; --vh: var(--vph, min(calc(100cqh - 3.75rem), var(--sh))); }
}

.p23-half { position: absolute; top: var(--s-2); left: calc(var(--x) * 1%); translate: -50% 0; margin: 0; font-weight: var(--fw-semibold); white-space: nowrap; }
.link.p23-divide { stroke: var(--rule); stroke-width: var(--stroke-link-app); }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p23-page--placed .p23-stage { flex-grow: 0; } }
